package cn.zhigeng.app;

import android.app.AlertDialog;
import android.content.*;
import android.os.*;
import android.provider.OpenableColumns;
import android.text.InputType;
import android.view.View;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** Install, search and resolve actual community scripts into the existing native player/cache. */
public class AnimeExtensionsActivity extends ReadingToolActivity {
    private AnimePluginRegistry registry;private AnimePluginEngine engine;private JSONObject anime,selected,episode;private JSONArray plugins=new JSONArray(),shown=new JSONArray(),servers=new JSONArray();
    private Spinner choices;private EditText query;private CheckBox dub;private TextView status,paging;private LinearLayout results;private Button search,previous,next,manage,local,index;
    private int page=1;private String phase="search";private boolean busy,destroyed;private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();
    protected AnimePluginRegistry createRegistry(){return new AnimePluginRegistry(this);}
    @Override public void onCreate(Bundle state){super.onCreate(state);try{String raw=getIntent().getStringExtra("anime");anime=raw==null?new JSONObject().put("id",0).put("title",new JSONObject().put("userPreferred","")):new JSONObject(raw);registry=createRegistry();}catch(Exception e){finish();return;}
        screen("社区视频源扩展");add(body,text("从扩展找到可播放剧集",23,INK),12);add(body,text("支持 Seanime / Anix 的 onlinestream-provider JavaScript / TypeScript 协议。由你添加仓库或脚本、选择匹配的作品与视频源；播放、续播和缓存使用知更原生播放器。",14,INK),10);
        index=button("添加扩展仓库 / 清单网址",false);local=button("导入本地 JS / TS 扩展",false);manage=button("管理已安装扩展",false);for(Button b:new Button[]{index,local,manage})add(body,b,10);
        index.setOnClickListener(v->repository());local.setOnClickListener(v->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),91);}catch(Exception e){error(e);}});manage.setOnClickListener(v->manage());
        add(body,text("选择视频源扩展",15,INK),16);choices=new Spinner(this);choices.setContentDescription("选择视频源扩展");choices.setMinimumHeight(dp(48));add(body,choices,6);
        add(body,text("动漫名称",15,INK),14);query=input("扩展搜索名称");query.setText(state==null?(anime.optLong("id")>0?AnimeCatalogClient.title(anime):""):state.getString("query",""));add(body,query,6);dub=new CheckBox(this);dub.setText("搜索配音版（由扩展提供）");dub.setMinHeight(dp(48));add(body,dub,8);
        search=button("搜索可播放剧集",true);add(body,search,12);search.setOnClickListener(v->search());Button library=button("已关联剧集与离线缓存",false);add(body,library,10);library.setOnClickListener(v->AnimeVideoLibraryActivity.open(this,anime));
        Button cancel=button("取消当前扩展请求",false);add(body,cancel,8);cancel.setOnClickListener(v->{AnimePluginEngine active=engine;if(active!=null)active.cancel();status.setText("正在取消，请稍候…");});
        status=text("先添加并启用你信任的视频源扩展",14,INK);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);add(body,status,14);results=column();add(body,results,10);paging=text("",13,INK);add(body,paging,12);
        LinearLayout nav=row();previous=button("扩展结果上一页",false);next=button("扩展结果下一页",false);nav.addView(previous,new LinearLayout.LayoutParams(0,-2,1));nav.addView(next,new LinearLayout.LayoutParams(0,-2,1));add(body,nav,8);previous.setOnClickListener(v->{if(page>1){page--;render();}});next.setOnClickListener(v->{if(page*20<shown.length()){page++;render();}});
        Button license=button("扩展运行时与开源许可",false);add(body,license,14);license.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("QuickJS / Anix / TypeScript").setMessage("QuickJS-KT（Apache 2.0）、QuickJS（MIT）、TypeScript（Apache 2.0）；Seanime 兼容前导代码适配自 Anix（MIT）。扩展在有内存和超时限制的独立 JS 上下文中执行，不提供文件、进程、知更账号接口。你导入的扩展可访问公网，来源网站的登录、地区、Cookie 或 DRM 要求可能使部分源不可用。\n许可文件随 APK 保存。").setPositiveButton("关闭",null).show());refresh();
    }
    private void refresh(){try{String current=selected==null?"":selected.optString("id");plugins=new JSONArray();ArrayList<String> names=new ArrayList<>();int position=0;JSONArray all=registry.installed();for(int i=0;i<all.length();i++){JSONObject p=all.getJSONObject(i);if(p.optBoolean("enabled")){if(p.optString("id").equals(current))position=plugins.length();plugins.put(p);names.add(p.optString("name"));}}if(names.isEmpty())names.add("尚无已启用扩展");choices.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));choices.setSelection(position);search.setEnabled(plugins.length()>0&&!busy);}catch(Exception e){error(e);}}
    interface Work{Object run()throws Exception;}interface Done{void run(Object value)throws Exception;}
    private void task(Work work,Done done){if(busy)return;busy=true;for(Button b:new Button[]{search,manage,local,index,previous,next})b.setEnabled(false);choices.setEnabled(false);status.setText("扩展正在处理，请稍候…");io.execute(()->{Object value=null;Exception error=null;try{value=work.run();}catch(Exception e){error=e;}final Object result=value;final Exception failed=error;ui.post(()->{if(destroyed)return;busy=false;for(Button b:new Button[]{manage,local,index})b.setEnabled(true);choices.setEnabled(true);refresh();previous.setEnabled(page>1);next.setEnabled(page*20<shown.length());try{if(failed!=null){closeEngine();throw failed;}done.run(result);}catch(Exception e){error(e);}});});}
    private void repository(){EditText url=input("扩展仓库 HTTPS 地址");new AlertDialog.Builder(this).setTitle("添加扩展仓库").setView(url).setNegativeButton("取消",null).setPositiveButton("读取清单",(d,w)->{String value=url.getText().toString().trim();task(()->registry.index(value),found->{JSONArray list=(JSONArray)found;if(list.length()==0){status.setText("清单没有可用的 onlinestream-provider 扩展");return;}String[] names=new String[list.length()];for(int i=0;i<names.length;i++)names[i]=list.getJSONObject(i).optString("name")+" · "+list.getJSONObject(i).optString("version");new AlertDialog.Builder(this).setTitle("选择要安装的扩展").setItems(names,(a,which)->confirmInstall(list.optJSONObject(which))).setNegativeButton("取消",null).show();});}).show();}
    private void confirmInstall(JSONObject manifest){new AlertDialog.Builder(this).setTitle("安装并启用 "+manifest.optString("name")+"？").setMessage("脚本来源："+manifest.optString("payloadURI")+"\n扩展将能执行脚本和请求公网。仅安装你信任的来源；同编号的旧扩展将被替换，已关联视频和缓存保留。")
        .setNegativeButton("取消",null).setPositiveButton("安装并启用",(d,w)->task(()->registry.install(manifest),installed->{selected=(JSONObject)installed;closeEngine();refresh();status.setText("扩展已安装，可配置偏好后搜索");})).show();}
    private void manage(){try{JSONArray all=registry.installed();if(all.length()==0){status.setText("还没有安装扩展");return;}String[] names=new String[all.length()];for(int i=0;i<names.length;i++){JSONObject p=all.getJSONObject(i);names[i]=p.optString("name")+(p.optBoolean("enabled")?" · 已启用":" · 已停用");}new AlertDialog.Builder(this).setTitle("已安装扩展").setItems(names,(d,which)->{JSONObject p=all.optJSONObject(which);new AlertDialog.Builder(this).setTitle(p.optString("name")).setItems(new String[]{p.optBoolean("enabled")?"停用":"启用","扩展偏好设置","移除扩展"},(a,action)->{try{if(action==1){preferences(p);return;}if(action==2){new AlertDialog.Builder(this).setTitle("移除此扩展？").setMessage("已关联的视频、本地原文件和缓存保留。").setNegativeButton("保留",null).setPositiveButton("移除",(x,y)->{try{registry.change(p.getString("id"),true,false);closeEngine();refresh();}catch(Exception e){error(e);}}).show();}else{registry.change(p.getString("id"),false,!p.optBoolean("enabled"));closeEngine();refresh();}}catch(Exception e){error(e);}}).setNegativeButton("关闭",null).show();}).setNegativeButton("关闭",null).show();}catch(Exception e){error(e);}}
    private void preferences(JSONObject p)throws Exception{EditText values=input("扩展偏好 JSON");values.setSingleLine(false);values.setMinLines(4);values.setText(registry.preferences(p.getString("id")).toString(2));new AlertDialog.Builder(this).setTitle("扩展偏好设置").setMessage("按扩展说明填写字符串键值，例如 {\"apiKey\":\"...\"}。在本机加密保存，只提供给这个扩展。").setView(values).setNegativeButton("取消",null).setPositiveButton("保存偏好",(d,w)->{try{registry.preferences(p.getString("id"),values.getText().toString());closeEngine();status.setText("扩展偏好已保存");}catch(Exception e){error(e);}}).show();}
    private void search(){if(plugins.length()==0)return;JSONObject plugin=plugins.optJSONObject(choices.getSelectedItemPosition());String term=query.getText().toString().trim();boolean dubbed=dub.isChecked();try{JSONObject options=AnimeProviderModel.search(anime,term,dubbed);task(()->{if(engine==null||selected==null||!selected.optString("hash").equals(plugin.optString("hash"))||!selected.optString("id").equals(plugin.optString("id"))){if(engine!=null)engine.close();engine=registry.engine(plugin);selected=plugin;}JSONObject settings=new JSONObject(engine.call("getSettings","[]"));servers=settings.optJSONArray("episodeServers");if(servers==null||servers.length()==0)servers=new JSONArray().put("default");return AnimeProviderModel.series(engine.call("search",new JSONArray().put(options).toString()));},value->{phase="search";shown=(JSONArray)value;page=1;render();status.setText("扩展搜索完成 · "+shown.length()+" 个结果，请选择匹配作品");});}catch(Exception e){error(e);}}
    private void render(){results.removeAllViews();for(int i=(page-1)*20;i<Math.min(page*20,shown.length());i++){JSONObject row=shown.optJSONObject(i);if(row==null)continue;String name=phase.equals("search")?row.optString("title"):"第 "+row.opt("number")+" 集 · "+row.optString("title","");Button action=button(name,false);add(results,action,10);action.setOnClickListener(v->{if(busy)return;if(phase.equals("search"))task(()->AnimeProviderModel.episodes(engine.call("findEpisodes",new JSONArray().put(String.valueOf(row.get("id"))).toString())),value->{phase="episodes";shown=(JSONArray)value;page=1;render();status.setText("找到 "+shown.length()+" 集，选择剧集获取视频源");});else{episode=row;chooseServer();}});}paging.setText("第 "+page+" 页 · "+shown.length()+" 项");previous.setEnabled(page>1&&!busy);next.setEnabled(page*20<shown.length()&&!busy);}
    private void chooseServer(){try{String[] names=new String[Math.min(servers.length(),30)];for(int i=0;i<names.length;i++)names[i]=servers.getString(i);new AlertDialog.Builder(this).setTitle("选择剧集服务器").setItems(names,(d,which)->{JSONObject chosen=episode;String server=names[which];task(()->AnimeProviderModel.streams(engine.call("findEpisodeServer",new JSONArray().put(chosen).put(server).toString())),value->{JSONArray streams=(JSONArray)value;if(streams.length()==0){status.setText("没有可用的 HTTPS 视频源，请换服务器或扩展");return;}String[] labels=new String[streams.length()];for(int i=0;i<labels.length;i++)labels[i]=streams.getJSONObject(i).optString("quality")+" · "+streams.getJSONObject(i).optString("format");new AlertDialog.Builder(this).setTitle("选择画质 / 视频源").setItems(labels,(x,index)->associate(chosen,streams.optJSONObject(index))).setNegativeButton("取消",null).show();});}).setNegativeButton("取消",null).show();}catch(Exception e){error(e);}}
    private void associate(JSONObject episode,JSONObject stream){try{EditText number=input("关联本地集数");number.setInputType(InputType.TYPE_CLASS_NUMBER);double source=episode.optDouble("number");number.setText(Integer.toString(source>=1&&source==Math.floor(source)?(int)source:1));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("保存并播放此集").setMessage("扩展集数："+episode.opt("number")+"\n请确认关联到本地的集数；已有同集记录会使用新来源。缓存后可在视频库离线观看；外置字幕只在联网播放时加载。").setView(number).setNegativeButton("取消",null).setPositiveButton("确认保存并播放",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{int n=Integer.parseInt(number.getText().toString());AnimeVideoStore store=new AnimeVideoStore(this,anime.optLong("id"));JSONObject old=store.episode(n);JSONObject updated=AnimeVideoModel.put(store.entries(),anime,n,episode.optString("title"),stream.getString("url"),stream.getString("format"));updated=AnimeVideoModel.transport(updated,n,stream.getJSONObject("options"));store.save(updated);JSONObject entry=updated.getJSONObject(Integer.toString(n));if(old!=null&&!old.optString("id").equals(entry.optString("id")))androidx.media3.exoplayer.offline.DownloadService.sendRemoveDownload(this,AnimeDownloadService.class,old.optString("id"),false);dialog.dismiss();startActivity(new Intent(this,AnimeVideoPlayerActivity.class).putExtra("episode",entry.toString()));}catch(Exception e){number.setError(e.getMessage());}}));dialog.show();}catch(Exception e){error(e);}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=91||result!=RESULT_OK||data==null||data.getData()==null)return;android.net.Uri uri=data.getData();task(()->{String name="本地扩展";try(android.database.Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>2*1024*1024)throw new Exception("脚本超过2 MB");out.write(bytes,0,n);}return new String[]{name,out.toString("UTF-8")};}},value->{String[] source=(String[])value;new AlertDialog.Builder(this).setTitle("安装并启用本地扩展？").setMessage(source[0]+"\n脚本将能执行并请求公网。请确认文件来自你信任的来源。").setNegativeButton("取消",null).setPositiveButton("安装并启用",(d,w)->task(()->registry.installLocal(source[0],source[1]),installed->{selected=(JSONObject)installed;closeEngine();refresh();status.setText("本地扩展已安装，可配置偏好后搜索");})).show();});}
    private void error(Exception e){if(status!=null)status.setText(Objects.toString(e.getMessage(),"扩展操作未完成，请重试"));}
    private void closeEngine(){AnimePluginEngine old=engine;engine=null;if(old!=null){old.cancel();new Thread(old::close,"stop-anime-extension").start();}}
    @Override protected void onSaveInstanceState(Bundle state){if(query!=null)state.putString("query",query.getText().toString());super.onSaveInstanceState(state);}
    @Override protected void onDestroy(){destroyed=true;closeEngine();io.shutdownNow();ui.removeCallbacksAndMessages(null);super.onDestroy();}
}
